"""
Fixed Product of Experts (PoE) Core Implementation

This module implements the core PoE system for Tölvera particle behaviors
without template routing. Each expert generates its own code that is
dynamically executed.
"""

import taichi as ti
import numpy as np
from typing import List, Dict, Any, Optional, Callable
import logging
import ast
import re
import hashlib

logger = logging.getLogger(__name__)

class SimpleProgrammaticExpert:
    """A single expert program generated by LLM."""
    
    def __init__(self, name: str, code: str, weight: float = 1.0):
        self.name = name
        self.code = code
        self.weight = weight
        self.function = None
        self.compiled_kernel = None
        
    def compile(self, namespace: Dict):
        """Compile the expert code."""
        try:
            # Execute the code to define the function
            exec(self.code, namespace)
            
            # Extract the function name from code
            match = re.search(r'def\s+(\w+)', self.code)
            if match:
                func_name = match.group(1)
                self.function = namespace[func_name]
                logger.debug(f"Successfully compiled expert {self.name}")
            else:
                logger.error(f"Could not find function definition in expert {self.name}")
        except Exception as e:
            logger.error(f"Failed to compile expert {self.name}: {e}")
            logger.error(f"Code was:\n{self.code}")
            raise

class PoEBehaviorSystem:
    """Product of Experts system for Tölvera particle behaviors."""
    
    def __init__(self, tolvera_instance):
        self.tv = tolvera_instance
        self.experts = []
        
        # Create force accumulator field
        self.force_accumulator = ti.Vector.field(2, dtype=ti.f32, shape=self.tv.pn)
        
        # Create expert force fields - one per expert for true independence
        self.expert_forces = {}
        
        # Namespace for expert compilation
        self.namespace = {
            'ti': ti,
            'np': np,
            'Vector': ti.Vector,
            'tv': self.tv
        }
        
        # Create unified kernel for applying forces
        self._create_force_application_kernel()
        
    def _create_force_application_kernel(self):
        """Create kernel for applying accumulated forces to particles."""
        @ti.kernel
        def apply_forces_to_particles(dt: ti.f32):
            for i in self.tv.p.field:
                if self.tv.p.field[i].active > 0:
                    # Apply accumulated forces to velocity
                    self.tv.p.field[i].vel += self.force_accumulator[i] * dt
                    
                    # Apply damping
                    self.tv.p.field[i].vel *= 0.98
                    
                    # Update position
                    self.tv.p.field[i].pos += self.tv.p.field[i].vel * dt
                    
        self.apply_forces_kernel = apply_forces_to_particles
    
    def add_expert(self, expert: SimpleProgrammaticExpert):
        """Add an expert to the system."""
        try:
            # Compile the expert
            expert.compile(self.namespace)
            
            # Create a dedicated force field for this expert
            force_field_name = f"force_{expert.name}"
            self.expert_forces[expert.name] = ti.Vector.field(2, dtype=ti.f32, shape=self.tv.pn)
            
            # Create a kernel that calls the expert function
            self._create_expert_kernel(expert)
            
            self.experts.append(expert)
            logger.info(f"Added expert {expert.name} with weight {expert.weight}")
            
        except Exception as e:
            logger.error(f"Failed to add expert {expert.name}: {e}")
            raise
    
    def _create_expert_kernel(self, expert: SimpleProgrammaticExpert):
        """Create a Taichi kernel that executes the expert's function."""
        
        # Generate a unique kernel for this expert
        kernel_code = f"""
@ti.kernel
def apply_expert_{expert.name}_kernel(tv: ti.template(), force_field: ti.template(), context_mouse_x: ti.f32, context_mouse_y: ti.f32):
    for i in range(tv.pn):
        if tv.p.field[i].active > 0:
            # Call the expert function to get force
            force = {expert.function.__name__}(tv, i)
            force_field[i] = force
"""
        
        # Add the expert function to namespace
        self.namespace[expert.function.__name__] = expert.function
        
        # Execute kernel code
        exec(kernel_code, self.namespace)
        
        # Store the kernel
        expert.compiled_kernel = self.namespace[f"apply_expert_{expert.name}_kernel"]
    
    def compute_forces(self, context: Dict[str, Any]):
        """Compute forces from all active experts using true PoE multiplication."""
        
        # Clear force accumulator
        self.force_accumulator.fill(0)
        
        # Get active experts with positive weights
        active_experts = [e for e in self.experts if e.weight > 0]
        
        if not active_experts:
            return
        
        # Compute Product of Experts normalization (multiplicative)
        # In true PoE, we multiply probabilities, here we use weights
        weight_product = np.prod([e.weight for e in active_experts])
        
        # Apply each expert independently
        for expert in active_experts:
            try:
                # Clear expert's force field
                self.expert_forces[expert.name].fill(0)
                
                # Execute expert kernel
                if expert.compiled_kernel:
                    expert.compiled_kernel(
                        self.tv,
                        self.expert_forces[expert.name],
                        context.get("mouse_x", 0.0),
                        context.get("mouse_y", 0.0)
                    )
                    
                    # Accumulate weighted forces (PoE multiplication)
                    self._accumulate_expert_forces(
                        expert.name, 
                        expert.weight / weight_product if weight_product > 0 else expert.weight
                    )
                    
            except Exception as e:
                logger.error(f"Failed to apply expert {expert.name}: {e}")
    
    @ti.kernel
    def _accumulate_expert_forces(self, expert_name: ti.template(), weight: ti.f32):
        """Accumulate forces from a single expert."""
        # Note: In a real implementation, we'd pass the force field directly
        # This is a simplified version for demonstration
        for i in self.force_accumulator:
            # This would access self.expert_forces[expert_name][i]
            # But Taichi doesn't support dynamic field access
            # So we need a different approach - see alternative implementation below
            pass
    
    def apply_forces(self, dt: float = 0.016):
        """Apply accumulated forces to particle velocities."""
        self.apply_forces_kernel(dt)
    
    def synthesize_expert_from_description(self, description: str, model) -> SimpleProgrammaticExpert:
        """Use LLM to generate expert code from natural language description."""
        
        prompt = f"""Generate a Taichi function that implements this particle behavior:
"{description}"

Rules:
1. Function should calculate a force (fx, fy) for particle i
2. Use Tölvera's particle system: tv.p.field[i].pos, tv.p.field[i].vel
3. Return the force as a ti.Vector([fx, fy])
4. Keep it simple and focused on ONE aspect
5. The function signature MUST be: @ti.func followed by def expert_NAME(tv: ti.template(), i: ti.i32) -> ti.math.vec2:

Example format:
@ti.func
def expert_behavior_name(tv: ti.template(), i: ti.i32) -> ti.math.vec2:
    # Access particle state
    pos = tv.p.field[i].pos
    vel = tv.p.field[i].vel
    
    # Calculate force
    force = ti.Vector([0.0, 0.0])
    
    # Your behavior logic here
    
    return force

Generate ONLY the function, no explanations:"""

        response = model.generate_content(prompt)
        
        # Extract code from response
        code = response.text
        if "```python" in code:
            code = code.split("```python")[1].split("```")[0]
        elif "```" in code:
            code = code.split("```")[1].split("```")[0]
            
        code = code.strip()
        
        # Extract function name for expert name
        match = re.search(r'def\s+(\w+)', code)
        name = match.group(1) if match else f"expert_{len(self.experts)}"
        
        return SimpleProgrammaticExpert(name, code)
    
    async def add_expert_from_description(self, description: str, model, weight: float = 1.0):
        """Generate and add an expert from natural language description."""
        
        expert = self.synthesize_expert_from_description(description, model)
        expert.weight = weight
        self.add_expert(expert)
        
        print(f"Added expert: {expert.name}")
        print(f"Code:\n{expert.code}\n")
        
        return expert


class PoEBehaviorSystemV2:
    """
    Alternative implementation that works around Taichi's limitations
    by using a different force combination strategy.
    """
    
    def __init__(self, tolvera_instance):
        self.tv = tolvera_instance
        self.experts = []
        
        # Single force field that all experts contribute to
        self.combined_forces = ti.Vector.field(2, dtype=ti.f32, shape=self.tv.pn)
        
        # Expert weights as Taichi field for kernel access
        self.max_experts = 50
        self.expert_weights = ti.field(dtype=ti.f32, shape=self.max_experts)
        
        # Namespace for compilation
        self.namespace = {
            'ti': ti,
            'np': np,
            'tv': self.tv
        }
        
    def add_expert(self, expert: SimpleProgrammaticExpert):
        """Add expert and create its execution wrapper."""
        
        if len(self.experts) >= self.max_experts:
            raise ValueError(f"Maximum number of experts ({self.max_experts}) reached")
        
        # Compile expert
        expert.compile(self.namespace)
        
        # Add to list and set weight
        expert_idx = len(self.experts)
        self.experts.append(expert)
        self.expert_weights[expert_idx] = expert.weight
        
        logger.info(f"Added expert {expert.name} at index {expert_idx}")
    
    def update_weights(self, new_weights: List[float]):
        """Update expert weights for gradient-based optimization."""
        for i, weight in enumerate(new_weights):
            if i < len(self.experts):
                self.experts[i].weight = weight
                self.expert_weights[i] = weight
    
    def compute_and_apply_forces(self, context: Dict[str, Any], dt: float = 0.016):
        """Compute all expert forces and apply them in one pass."""
        
        # Clear forces
        self.combined_forces.fill(0)
        
        # Compute PoE normalization
        active_experts = [e for e in self.experts if e.weight > 0]
        if not active_experts:
            return
            
        weight_product = np.prod([e.weight for e in active_experts])
        
        # Apply each expert's contribution
        for i, expert in enumerate(self.experts):
            if expert.weight > 0:
                normalized_weight = expert.weight / weight_product if weight_product > 0 else expert.weight
                
                # Create and execute expert-specific kernel
                self._execute_expert(expert, normalized_weight, context)
        
        # Apply combined forces to particles
        self._apply_combined_forces(dt)
    
    def _execute_expert(self, expert: SimpleProgrammaticExpert, weight: float, context: Dict[str, Any]):
        """Execute a single expert and accumulate its forces."""
        
        # Create a kernel that wraps the expert function
        @ti.kernel
        def apply_expert(forces: ti.template(), weight_value: ti.f32):
            for i in range(self.tv.pn):
                if self.tv.p.field[i].active > 0:
                    # Get force from expert function
                    force = expert.function(self.tv, i)
                    
                    # Accumulate weighted force
                    forces[i] += force * weight_value
        
        # Execute kernel
        apply_expert(self.combined_forces, weight)
    
    @ti.kernel
    def _apply_combined_forces(self, dt: ti.f32):
        """Apply accumulated forces to particle velocities."""
        for i in self.tv.p.field:
            if self.tv.p.field[i].active > 0:
                # Update velocity with combined force
                self.tv.p.field[i].vel += self.combined_forces[i] * dt
                
                # Damping
                self.tv.p.field[i].vel *= 0.98
                
                # Update position
                self.tv.p.field[i].pos += self.tv.p.field[i].vel * dt
    
    async def add_expert_from_description(self, description: str, model, weight: float = 1.0):
        """Generate and add expert from natural language."""
        
        # Use the synthesis method from V1
        system_v1 = PoEBehaviorSystem(self.tv)
        expert = system_v1.synthesize_expert_from_description(description, model)
        expert.weight = weight
        
        self.add_expert(expert)
        return expert